--模式1
---@class SceneGuideMode1_Model : GuideModeBase_Model @
---@field super GuideModeBase_Model @GuideModeBase_Model
local M = class("SceneGuideMode1_Model",Battle.GuideModeBase_Model)

--模式1
--
function M:init( scene, mode )
    M.super.init(self, scene, mode )
    --挂机战斗总每波怪最大数量
    self.maxMonsterNum = self.stageIdleData.idle_monster_num or 8;
    --当前的怪物数量
    self.curMonsterNum = self.maxMonsterNum;
    self.curMonsterIndex = 1;
    self:set_dir( FixVector3.right() );
    --当前等待时间
    self.timeIndex = 0;
    self.moveTime = 1;
    self.waitHitEnemyTime = self:getTime();
    self.curWaitHitEnemyTime = self.waitHitEnemyTime;
    --Logger.logError(self.config," config >> ")
    --Logger.logError(" 挂机敌人移动次数 >> "..self.moveTime.." 移动时间 >> "..self.waitHitEnemyTime)
    --当前场景中存在的最大怪物数量
    self.curSceneLiveMonsterNum = 3;
    self.fristTime = true;
    --开始先不创建敌人
    self.checkEnemy = false;
    --移动速度
    self.curSpeed = GlobalTools.base6;
    --敌人死完了，需要等待时间
    self.waitTime = GlobalTools.base3;
    self.curWaitTime =  self.waitTime;
    --起始位置
    -- -80
    -- -4.4
    self.startPosition.x = -47616;
    self.startPosition.y = 0;
    self.startPosition.z = -4505;
    
    --设定位置
    self:setPos( self.startPosition );
    self:resetPlayerPosition();
end


function M:getTime()
    if self.config ~= nil then
        if self.timeIndex >= self.config.times.Count then
            self.timeIndex = 0;
        end
        local config = GlobalTools:CommonToFix(self.config.times[self.timeIndex]);
        self.timeIndex = self.timeIndex + 1;
        return config;
    end
    return GlobalTools.base6;
end

--设定位置前,子类重写
function M:setPositionBefore( pos )
    self.maxLength = 116224;
    self.triggerDis = GlobalTools.base13
    --每隔5秒创建一波敌人
    self.createEnemyTime = GlobalTools.base3;
    --当前创建敌人的时间
    self.curCreateEnemyTime = self.createEnemyTime;
end

--检测主人 的位置
function M:checkMainPlayerPosition()
    --我和要追的点的距离
    --人物拉回原地
    if self.scene.mainPlayer ~= nil then
        local pos = self.scene.mainPlayer.position;
        if pos.x >= self.maxLength then
            --重新设定所有玩家的位置
            self:resetPlayerPosition();
            --guide拉回原地
            self:reset()
        end
    end
end


--重置
function M:reset()
    self.timeIndex = 0;
    self.moveTime = 1;
    self.waitHitEnemyTime = self:getTime();
    self.curWaitHitEnemyTime = self.waitHitEnemyTime;
    self:setPos( self.startPosition )
end


--重新设置玩家位置
function M:resetPlayerPosition()
    local players = self.scene.plyMgr:getPlayers(1);
    --别的英雄重新排位
    for i = 1, players.Count do
        local player = players:get(i-1)
        --第一个近战攻击
        local pos = self.scene:findSpawnPosition(1, player:get_index())
        player:setPos(pos)
    end
end

--移动模式
function M:moveMode(dt)
    self:checkMainPlayerPosition();
    --向导移动
    if self.curWaitHitEnemyTime > 0 then
        self.curWaitHitEnemyTime = self.curWaitHitEnemyTime - dt;
        local forward = self:get_dir();
        local forward_speed = forward * self.curSpeed
        local outPos = forward_speed * dt
        self:setPos( self.position + outPos )
        if self.curWaitHitEnemyTime <= 0 then
            self.curWaitHitEnemyTime = 0;
            self.checkEnemy = true;
            SelectTargetTool:clear();
        end
    end

    --开始检测敌人 
    if self.checkEnemy then
        local enemys = self.scene.plyMgr:getPlayers(-1)
        if self.curMonsterNum > 0 then
            if enemys.Count < self.curSceneLiveMonsterNum then
                local random_x = 0
                if self.dir > 0 then
                    random_x = -GlobalTools.base10;
                    self.dir = -1
                else
                    random_x = GlobalTools.base10;
                    self.dir = 1
                end
                local random_z = GlobalTools:ToFix( math.random(-5, 5) )
                local monster_data = self.monster_list:get(self.curMonsterIndex-1)
                if self.fristTime then
                    random_x = GlobalTools.base10;
                end
                self:enemyCreateRandom(random_x, random_z, monster_data )
                self.curMonsterIndex = self.curMonsterIndex + 1;
                if self.curMonsterIndex > self.monster_list.Count then
                    self.curMonsterIndex = 1;
                end
                self.curMonsterNum = self.curMonsterNum - 1;
            else
                if self.fristTime then
                    self.fristTime = false;
                end
            end
        else
            if enemys.Count <= 0 then
                if self.curWaitTime > GlobalTools.base0 then
                    self.curWaitTime = self.curWaitTime - dt;
                    if self.curWaitTime <= GlobalTools.base0 then
                        self.moveTime = self.moveTime + 1;
                        self.waitHitEnemyTime = self:getTime();
                        --Logger.logError(" 挂机敌人移动次数 >> "..self.moveTime.." 移动时间 >> "..self.waitHitEnemyTime)
                        self.curWaitHitEnemyTime = self.waitHitEnemyTime;
                        --当前的怪物数量
                        self.curMonsterNum = self.maxMonsterNum;
                        self.curMonsterIndex = 1
                        self.checkEnemy = false;
                        self.fristTime = true;
                        self.curWaitTime =  self.waitTime;
                    end
                end
            end
        end
    end
end


return M